import {practicalRateTasks,practicalRateCorrect} from './practical-rate-models.js?v=20261023-physicscomplete01';
import {showRatePractical} from './practical-rate-scenes.js?v=20261023-physicscomplete01';
export function mountRatePractical(l,p,root,{save,done,feedback}){const w=p.widget;w.task??=0;w.answers??={};w.passed??=[];const i=w.task%4,t=practicalRateTasks[i],a=w.answers[t.id]??={};w.answers[t.id]=a;const $=s=>root.querySelector(s);const select=(id,label,opts)=>`<label class="field-label" for="rp-${id}">${label}</label><select class="lab-select" id="rp-${id}"><option value="">Choose…</option>${opts.map(([v,s])=>`<option value="${v}">${s}</option>`).join('')}</select>`,field=(id,label)=>`<label class="field-label" for="rp-${id}">${label}</label><input class="lab-input" id="rp-${id}" type="number" step="any">`;let body=`<p><b>${i+1} / 4 · ${t.title}</b></p><p>${t.prompt}</p>`,keys=[];
if(t.id==='gas'){body+=field('rateA','A mean rate / cm³/s')+field('rateB','B mean rate / cm³/s')+select('final','Final hydrogen amount',[['same','Same'],['B','Greater in B'],['A','Greater in A']]);keys=['rateA','rateB','final'];}else if(t.id==='turbidity'){a.cloud??='0';body+=field('water','Water added / cm³')+field('concentration','Diluted stock before acid / g/dm³')+select('faster','Faster to the same endpoint',[['dilute','Dilute trial'],['stock','Stock trial'],['same','Same rate']])+'<label class="field-label" for="rp-cloud">Explore cloudiness · illustrative</label><input class="lab-input" id="rp-cloud" type="range" min="0" max="100" step="10">';keys=['water','concentration','faster','cloud'];}else{body+=t.fields.map(([id,label,opts])=>select(id,label,opts)).join('');keys=t.fields.map(f=>f[0]);}
root.innerHTML=body+'<button class="secondary" id="checkRP">Check reasoning</button><button class="secondary" id="nextRP">Next task →</button><p id="rpProgress">'+w.passed.length+' / 4 correct</p>';const draw=()=>showRatePractical(t.id,a.cloud,w.passed.includes(t.id)&&practicalRateCorrect(t,a));for(const k of keys){const el=$('#rp-'+k);el.value=a[k]??'';el[el.tagName==='INPUT'?'oninput':'onchange']=e=>{a[k]=e.target.value;save();draw();};}draw();$('#checkRP').onclick=()=>{if(!practicalRateCorrect(t,a)){feedback(t.id==='gas'?'Divide each20-second gas volume by20. With equal limiting magnesium and excess acid, compare speed separately from final amount.':t.id==='turbidity'?'Water makes stock plus water total50 cm³. Diluted concentration = stock concentration × stock volume ÷ combined volume, before acid addition. A shorter comparable endpoint time means faster change.':'Change concentration while controlling other rate factors. Check collection leaks, starting method and consistent endpoint judgement; repeat rather than selecting only convenient results.',true);return;}if(!w.passed.includes(t.id))w.passed.push(t.id);save();draw();$('#rpProgress').textContent=w.passed.length+' / 4 correct';feedback('Correct: the controlled comparison and interpretation agree.');if(w.passed.length===4){p.widgetDone=true;save();done();}};$('#nextRP').onclick=()=>{w.task=(i+1)%4;save();feedback('');mountRatePractical(l,p,root,{save,done,feedback});};}
